const rows = $json.rows;
const weekStart = $('Set Report Context').first().json.weekStart;
const destinationKey = $('Set Report Context').first().json.destinationKey;

let totalProjects = 0;
const interns = rows.map((row) => {
  const projects = Array.isArray(row.projects) ? row.projects : [];
  totalProjects += projects.length;
  return {
    internshipId:      row.internship_id,
    internEmployeeId:  row.intern_employee_id,
    internUserId:      row.intern_user_id,
    name:              row.intern_name || 'Unnamed Associate',
    email:             row.intern_email,
    department:        row.department || 'Unassigned',
    totalProjects:     row.total_projects || projects.length,
    projects
  };
});

return [{ json: { weekStart, destinationKey, totalInterns: interns.length, totalProjects, interns } }];

const body = items[0]?.json?.body;
const existingRows = Array.isArray(body) ? body : [];
const grouped = $('Group Interns').first().json;
const runExists = existingRows.some((row) => row.status === 'sent');

return [{ json: { ...grouped, existingRunId: existingRows.length > 0 ? (existingRows[0].id ?? null) : null, runExists } }];

const grouped = $json;
const div = '━━━━━━━━━━━━━━━━━━';
const output = [];

const healthEmoji = { on_track: '✅', at_risk: '⚠️', overdue: '🔴' };
const statusEmoji = { active: '🟢', planning: '🔵', on_hold: '⏸', completed: '✅', archived: '📦' };

// Industry Standard Helper: Sanitizes raw database values for UI presentation
const normalizeText = (str) => {
  if (!str) return '—';
  return str
    .replace(/_/g, ' ')                          // Replace all underscores with spaces
    .replace(/\b\w/g, (char) => char.toUpperCase()); // Capitalize the first letter of each word
};

const fmtMilestone = (ms) => {
  if (!ms) return '<i>No milestone set</i>';
  const statusLabel = normalizeText(ms.status);
  return `${ms.title || 'Untitled'} — <i>${statusLabel}</i> (${ms.progress_pct ?? 0}%)`;
};

for (const associate of grouped.interns) {
  const lines = [
    `<b>Control Hub | Weekly Projects Digest</b>`,
    ``,
    `📅 <b>Week of:</b> ${grouped.weekStart}`,
    `🏢 <b>Department:</b> ${associate.department}`,
    ``,
    div,
    ``,
    `👤 <b>${associate.name}</b>`,
    `📊 <b>Total Projects:</b> ${associate.totalProjects}`,
  ];

  const projects = Array.isArray(associate.projects) ? associate.projects : [];
  for (const proj of projects) {
    const he = healthEmoji[proj.health] || '❓';
    const se = statusEmoji[proj.status] || '❓';

    lines.push(``);
    lines.push(`📁 <b>${proj.name}</b>  ${se} ${he}`);
    // Applied the normalizeText utility below
    lines.push(`  ${he} Health: ${normalizeText(proj.health)}`);
    lines.push(`  ${se} Status: ${normalizeText(proj.status)}`);
    lines.push(`  📈 Progress: <b>${proj.progress_pct ?? 0}%</b>  |  🏅 Pts: <b>${proj.points_total ?? 0}</b>`);
    lines.push(`  📌 Milestone: ${fmtMilestone(proj.monthly_milestone)}`);
  }

  lines.push(``);
  lines.push(div);

  output.push({ json: { telegramText: lines.join('\n') } });
}

return output;

// One output item per department — avoids one giant merged message
const grouped = $('Merge Run State').first().json;
const div = '━━━━━━━━━━━━━━━━━━';
const output = [];

const deptMap = new Map();
for (const associate of grouped.interns) {
  if (!deptMap.has(associate.department)) deptMap.set(associate.department, []);
  deptMap.get(associate.department).push(associate);
}

for (const [dept, deptInterns] of Array.from(deptMap).sort(([a], [b]) => a.localeCompare(b))) {
  const lines = [
    `🗓 <b>Weekly Projects Digest</b> | ${grouped.weekStart}`,
    div,
    ``,
    `🏢 <b>${dept.toUpperCase()}</b>`,
  ];

  for (const associate of deptInterns) {
    const projects = Array.isArray(associate.projects) ? associate.projects : [];
    const risks = projects.filter(p => p.health === 'at_risk' || p.health === 'overdue');
    const progressSummary = projects.length > 0
      ? projects.map(p => `${p.name} (${p.progress_pct ?? 0}%)`).join(', ')
      : 'No active projects';
    const riskText = risks.length > 0
      ? risks.map(p => `${p.name} — ${(p.health || '').replace(/_/g, ' ')}`).join('; ')
      : 'None';
    lines.push(``);
    lines.push(`• <b>${associate.name}</b> (${associate.totalProjects} project${associate.totalProjects !== 1 ? 's' : ''})`);
    lines.push(`  ↳ <i>Progress:</i> ${progressSummary}.`);
    lines.push(`  ↳ <i>Risks:</i> ${riskText}.`);
  }

  lines.push(``);
  lines.push(div);

  output.push({ json: { ...grouped, department: dept, telegramText: lines.join('\n') } });
}

return output;

// Re-anchor to grouped state; check if any dept Telegram send succeeded
const grouped = $('Merge Run State').first().json;
const sends = $input.all();
const anySuccess = sends.some(i => i.json?.result?.message_id);
return [{ json: { ...grouped, digestSent: anySuccess } }];
